 let run=0,timer;
 const state=(name,text,checked)=>{box.dataset.state=name;box.setAttribute('aria-checked',String(checked));box.setAttribute('aria-busy',String(name==='working'));label.textContent=text;hint.textContent=hints[name]||'';};
