 systemCheck.state='working';systemCheck.step=0;emit();if(force&&announce)toast('Consultando la versión publicada','info',undefined,{title:'Comprobando actualizaciones…',release:'checking',id:'system-check',duration:0});
 systemCheck.running=api('/api/system/check',{}).then(async info=>{systemCheck.step=1;emit();await frame();systemCheck.step=2;emit();await frame();Object.assign(systemCheck,{state:'done',info,error:'',lastSuccess:info.checked_at});try{sessionStorage.setItem(key,JSON.stringify({info,at:info.checked_at}));}catch{}
   if(info.update_available){let told='';try{told=sessionStorage.getItem(key+':aviso')||'';}catch{}if(told!==info.latest.version||force){dismissToast('system-check');toast('Release '+info.latest.version+' listo para cargar','info',autoUpdate.server?{label:'Actualizar ahora',run:()=>autoApply(true)}:{label:'Ver novedades',run:()=>go('system')},{title:'Nueva actualización disponible',duration:10000,release:'new',secondary:{label:'Posponer',run:()=>{if(autoUpdate.server)autoPostpone();}}});try{sessionStorage.setItem(key+':aviso',info.latest.version);}catch{}}}else if(force&&announce){dismissToast('system-check');toast('Versión '+(info.installed?info.installed.version:document.body.dataset.version)+' activa','success',undefined,{title:'Sistema actualizado',release:'done',duration:5000});}dismissToast('system-check');return info;})
  .catch(error=>{Object.assign(systemCheck,{state:'error',error:error.message});dismissToast('system-check');if(force&&announce)toast(error.message||'Sin respuesta del servidor','error',{label:'Reintentar',run:()=>runSystemCheck(true)},{title:'No se pudo comprobar la versión',release:'error',duration:9000});return null;})
  .finally(()=>{systemCheck.running=null;document.dispatchEvent(new CustomEvent('systemcheck'));});
