// Confirmación propia (estilo macOS) para cerrar con cambios sin guardar. Sustituye a window.confirm en los cierres internos:
// foco inicial en la opción segura, Escape cancela el descarte y nunca se abren dos a la vez. Devuelve 'keep', 'discard' o 'extra'.
let confirmOpen=null;
function confirmClose({title,text,keep='Seguir editando',discard='Descartar y cerrar',extra}){
 if(confirmOpen)return confirmOpen;
 confirmOpen=new Promise(resolve=>{const dialog=el('dialog',undefined,'confirm-mac'),icon=el('span',undefined,'confirm-mac-icon'),heading=el('h2',title),body=el('p',text),actions=el('div',undefined,'confirm-mac-actions');let answer='keep',closing=false;
  dialog.dataset.enhanced='true';dialog.setAttribute('role','alertdialog');heading.id='confirm-mac-title';body.id='confirm-mac-text';dialog.setAttribute('aria-labelledby',heading.id);dialog.setAttribute('aria-describedby',body.id);icon.append(systemIcon('M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7z M14 2v4a2 2 0 0 0 2 2h4 M12 9v4 M12 17h.01'));
  const finish=value=>{if(closing)return;closing=true;answer=value;dialog.classList.add('confirm-mac-closing');setTimeout(()=>dialog.close(),matchMedia('(prefers-reduced-motion: reduce)').matches?0:150);};
  const stay=button(keep,()=>finish('keep'),'primary'),leave=button(discard,()=>finish('discard'),'secondary confirm-mac-discard');actions.append(stay);if(extra)actions.append(button(extra,()=>finish('extra'),'secondary'));actions.append(leave);
  dialog.append(icon,heading,body,actions);document.body.append(dialog);
  dialog.addEventListener('cancel',event=>{event.preventDefault();finish('keep');});dialog.addEventListener('click',event=>{if(event.target===dialog)finish('keep');});
  dialog.addEventListener('close',()=>{dialog.remove();confirmOpen=null;resolve(answer);},{once:true});dialog.showModal();stay.focus();});
 return confirmOpen;
}
