 function setMenu(open,focus=false){menuOpen=open;drawer.hidden=innerWidth<1000&&!open;menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Cerrar navegación principal':'Abrir navegación principal');if(open){closeAccount();refreshWeather();}if(focus)returnFocus.focus();}
