 document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('assistance-menu').open){closeAssistance();$('assistance-menu').querySelector('summary').focus();event.preventDefault();}else if(accountOpen){closeAccount(true);event.preventDefault();}else if(menuOpen){setMenu(false,true);event.preventDefault();}}});
