async function requestModalClose(dialog){if(confirmOpen)return;const form=dialog.querySelector('form');if(form){if([...form.querySelectorAll('button')].some(button=>button.type==='submit'&&button.disabled)||form.getAttribute('aria-busy')==='true')return;if(dialog.dataset.baseline&&formSnapshot(form)!==dialog.dataset.baseline&&await confirmClose({title:'¿Cerrar sin guardar?',text:'Tienes cambios sin guardar. Si sales ahora, perderás las modificaciones pendientes.'})==='keep')return;}dialog.close();}
