 const confirmed=el('label',undefined,'access-confirm'),check=el('input');check.type='checkbox';check.name='access_confirmed';confirmed.append(check,el('span','Confirmo que el cliente expresó esta decisión y el alcance seleccionado.'));box.append(confirmed);error('access_confirmed');
 const destructive=field(box,'Autorización adicional: reinstalar, formatear o eliminar información','destructive_action','',{select:true});for(const[value,text]of [['not_requested','No solicitada: sin autorización adicional'],['authorized','Sí, mediante autorización adicional expresa'],['denied','No autorizo reinstalar ni eliminar información']]){const option=el('option',text);option.value=value;destructive.append(option);}
