function renderOrdersList(data,params){
 const root=$('module-content');root.replaceChildren();const add=$('module-add');add.hidden=false;add.textContent='+ Nueva orden';add.onclick=()=>showOrder();
 const search=el('form',undefined,'orders-search');search.setAttribute('role','search');search.setAttribute('aria-label','Buscar órdenes');const input=el('input');input.type='search';input.name='q';input.maxLength=150;input.value=params.get('q')||'';input.placeholder='Número de orden, cliente, equipo, identificación o teléfono';input.setAttribute('aria-label','Buscar por orden, cliente, equipo, identificación o teléfono');const submit=el('button','Buscar','primary');submit.type='submit';search.append(input,submit);search.onsubmit=async e=>{e.preventDefault();if(submit.disabled)return;submit.disabled=true;const value=input.value.trim();try{if(/^(?:PCD-\d{8}-\d{4,}|OP-\d+)$/i.test(value)){try{const match=await api('/api/order-by-code/'+encodeURIComponent(value.toUpperCase()));go('orders',new URLSearchParams({id:String(match.id)}));return;}catch(error){if(error.status!==404)throw error;}}const next=new URLSearchParams(params);next.delete('page');if(value)next.set('q',value);else next.delete('q');go('orders',next);}catch(error){notify(error.message);}finally{submit.disabled=false;}};root.append(search);appendOrderFilters(root,params);
 const results=el('section',undefined,'data-panel orders-results');results.setAttribute('aria-label','Resultados de órdenes');const bar=el('div',undefined,'orders-results-heading');const count=el('p',data.total+(data.total===1?' registro':' registros'),'result-count');count.setAttribute('role','status');bar.append(count,el('small',data.total?'Mostrando '+((data.page-1)*50+1)+'–'+Math.min(data.page*50,data.total)+' de '+data.total:'Sin resultados'));results.append(bar);const wrap=el('div');if(data.rows.length)renderOrderCards(wrap,data.rows);else{wrap.className='orders-empty';wrap.append(operationIcon('order'),el('h3',params.size?'No hay órdenes para esta búsqueda.':'Todavía no hay órdenes registradas.'),el('p',params.size?'Ajusta la búsqueda o los filtros para encontrar otras órdenes.':'Registra una orden para iniciar el seguimiento del equipo.'));}results.append(wrap);
 const pager=el('nav',undefined,'pager orders-pagination');pager.setAttribute('aria-label','Paginación de órdenes');const previous=button('Anterior',()=>page(-1)),next=button('Siguiente',()=>page(1));previous.disabled=data.page<=1;next.disabled=data.page>=data.pages;const indicator=el('span',`Página ${data.page} de ${data.pages}`);indicator.setAttribute('aria-current','page');pager.append(previous,indicator,next);results.append(pager);root.append(results);
 function page(offset){const next=new URLSearchParams(params);next.set('page',String(data.page+offset));go('orders',next);}
}
function orderActionsMenu(row){
 const trigger=button('Más acciones',toggle,'orders-more-trigger');trigger.setAttribute('aria-haspopup','menu');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label','Más acciones de '+displayCode(row));const menu=el('div',undefined,'orders-action-menu');menu.id='orders-actions-'+row.id;menu.dataset.orderActionPopover='true';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Acciones de '+displayCode(row));trigger.setAttribute('aria-controls',menu.id);const native=typeof menu.showPopover==='function';if(native)menu.setAttribute('popover','auto');else menu.hidden=true;document.body.append(menu);
 function isOpen(){return native?menu.matches(':popover-open'):!menu.hidden;}
 function close(restore=false){if(native&&isOpen())menu.hidePopover();else if(!native)menu.hidden=true;trigger.setAttribute('aria-expanded','false');if(restore)trigger.focus();}
 function toggle(){if(isOpen()){close();return;}document.querySelectorAll('[data-order-action-popover]').forEach(other=>{if(other===menu)return;if(typeof other.hidePopover==='function'){if(other.matches(':popover-open'))other.hidePopover();}else other.hidden=true;});if(native)menu.showPopover();else menu.hidden=false;trigger.setAttribute('aria-expanded','true');const r=trigger.getBoundingClientRect(),m=menu.getBoundingClientRect(),margin=12;menu.style.left=Math.max(margin,Math.min(r.right-m.width,innerWidth-m.width-margin))+'px';menu.style.top=(r.bottom+m.height+margin<=innerHeight?r.bottom+6:Math.max(margin,r.top-m.height-6))+'px';menu.querySelector('button')?.focus();}
 if(native)menu.addEventListener('toggle',()=>trigger.setAttribute('aria-expanded',String(isOpen())));
 function item(label,action,icon){const b=button('',()=>{close(true);Promise.resolve().then(action).catch(error=>notify(error.message));},'orders-menu-item');b.setAttribute('role','menuitem');b.append(orderActionIcon(icon),document.createTextNode(label));menu.append(b);}
 if(admin()){item('Editar',()=>openOrderEditor(row.id),'edit');item('Cambiar estado',()=>openOrderStatusDialog(row),'service');}
 item('Ver historial',()=>go('orders',new URLSearchParams({id:String(row.id),section:'history'})),'service');item('Reimprimir comprobante',()=>showDocumentPreview(row.id,'receipt'),'document');item('Compartir',()=>shareReceipt(row.id),'share');item('Etiqueta de servicio',()=>printEquipmentLabel(row),'tag');item('Duplicar orden',()=>duplicateOrder(row.id),'document');
 menu.addEventListener('keydown',e=>{const items=[...menu.querySelectorAll('button')],index=items.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();close(true);}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[next].focus();}});trigger.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();if(!isOpen())toggle();}});return trigger;
}
function dismissOrderMenus(event){document.querySelectorAll('[data-order-action-popover]').forEach(menu=>{const trigger=document.querySelector('[aria-controls="'+menu.id+'"]');if(event?.type==='click'&&(menu.contains(event.target)||trigger?.contains(event.target)))return;if(typeof menu.hidePopover==='function'){if(menu.matches(':popover-open'))menu.hidePopover();}else menu.hidden=true;trigger?.setAttribute('aria-expanded','false');});}
document.addEventListener('click',dismissOrderMenus);window.addEventListener('resize',dismissOrderMenus);document.addEventListener('scroll',event=>{if(!event.target.closest?.('[data-order-action-popover]'))dismissOrderMenus();},true);
function openOrderStatusDialog(row){
 const dialog=smallDialog('Cambiar estado · '+displayCode(row)),form=el('form');form.className='orders-status-form';const select=field(form,'Estado de la orden','status',row.status_code,{select:true});for(const[code,label]of Object.entries(statusNames))select.append(new Option(label,code));select.value=row.status_code;const message=el('p','','message');message.setAttribute('role','status');const save=el('button','Guardar estado','primary');save.type='submit';form.append(message,save);dialog.append(form);select.focus();form.onsubmit=async event=>{event.preventDefault();if(save.disabled)return;save.disabled=true;try{await api('/api/order-status',{id:String(row.id),status:select.value});dialog.close();await renderRoute();notify('Estado actualizado.',true);}catch(error){message.textContent=error.message;}finally{save.disabled=false;}};
}
